import React, { useState, useEffect } from 'react';
import { useSearchParams, Link } from 'react-router-dom';
import api from '../services/api';
import { FiMapPin } from 'react-icons/fi';

const Home = () => {
    const [searchParams] = useSearchParams();
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [category, setCategory] = useState('todos');
    const [stats, setStats] = useState(null);

    useEffect(() => {
        fetchStats();
        fetchProducts();
    }, [category, searchParams]);

    const fetchStats = async () => {
        try {
            const response = await api.get('/stats');
            setStats(response.data);
        } catch (error) {
            console.error('Erro ao buscar estatísticas:', error);
        }
    };

    const fetchProducts = async () => {
        setLoading(true);
        try {
            const search = searchParams.get('search') || '';
            const response = await api.get('/products', {
                params: { category: category !== 'todos' ? category : undefined, search, limit: 12 }
            });
            setProducts(response.data.products);
        } catch (error) {
            console.error('Erro ao buscar produtos:', error);
        } finally {
            setLoading(false);
        }
    };

    const categories = [
        { id: 'todos', name: 'Todos', icon: '📦' },
        { id: 'telemovel', name: 'Telemóveis', icon: '📱' },
        { id: 'laptop', name: 'Laptops', icon: '💻' },
        { id: 'console', name: 'Consoles', icon: '🎮' },
        { id: 'tablet', name: 'Tablets', icon: '📟' }
    ];

    const getCategoryIcon = (category) => {
        const icons = { telemovel: '📱', laptop: '💻', console: '🎮', tablet: '📟' };
        return icons[category] || '📦';
    };

    return (
        <div>
            {/* Hero Section */}
            <div className="bg-gradient-to-r from-primary-600 to-primary-800 text-white rounded-2xl p-8 mb-8 text-center">
                <h1 className="text-3xl md:text-4xl font-bold mb-4">
                    Compre e Venda Eletrônicos Usados com Segurança
                </h1>
                <p className="text-lg md:text-xl mb-6 opacity-90">
                    O marketplace mais confiável de Luanda. Milhares de produtos disponíveis!
                </p>
                <div className="flex justify-center gap-4">
                    <Link to="/register" className="bg-white text-primary-600 px-6 py-3 rounded-lg font-semibold hover:bg-gray-100 transition">
                        Começar a Comprar
                    </Link>
                    <Link to="/register" className="border-2 border-white text-white px-6 py-3 rounded-lg font-semibold hover:bg-white hover:text-primary-600 transition">
                        Anunciar Grátis
                    </Link>
                </div>
            </div>

            {/* Estatísticas */}
            {stats && (
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
                    <div className="bg-white rounded-lg p-4 text-center shadow">
                        <div className="text-2xl font-bold text-primary-600">{stats.totalProducts}</div>
                        <div className="text-sm text-gray-600">Produtos</div>
                    </div>
                    <div className="bg-white rounded-lg p-4 text-center shadow">
                        <div className="text-2xl font-bold text-primary-600">{stats.totalUsers}</div>
                        <div className="text-sm text-gray-600">Usuários</div>
                    </div>
                    <div className="bg-white rounded-lg p-4 text-center shadow">
                        <div className="text-2xl font-bold text-primary-600">{stats.totalSellers}</div>
                        <div className="text-sm text-gray-600">Vendedores</div>
                    </div>
                    <div className="bg-white rounded-lg p-4 text-center shadow">
                        <div className="text-2xl font-bold text-primary-600">100%</div>
                        <div className="text-sm text-gray-600">Seguro</div>
                    </div>
                </div>
            )}

            {/* Categorias */}
            <div className="flex flex-wrap gap-2 mb-6">
                {categories.map(cat => (
                    <button
                        key={cat.id}
                        onClick={() => setCategory(cat.id)}
                        className={`px-4 py-2 rounded-full flex items-center gap-2 transition ${
                            category === cat.id
                                ? 'bg-primary-600 text-white'
                                : 'bg-white text-gray-700 hover:bg-gray-100'
                        }`}
                    >
                        <span>{cat.icon}</span>
                        <span>{cat.name}</span>
                    </button>
                ))}
            </div>

            {/* Produtos */}
            <h2 className="text-2xl font-bold mb-4">Últimos Anúncios</h2>
            {loading ? (
                <div className="flex justify-center py-12">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
                </div>
            ) : products.length === 0 ? (
                <div className="bg-white rounded-xl p-12 text-center">
                    <p className="text-gray-500">Nenhum produto encontrado.</p>
                    <p className="text-sm text-gray-400 mt-2">Seja o primeiro a anunciar um produto!</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                    {products.map(product => (
                        <Link to={`/product/${product.id}`} key={product.id} className="block">
                            <div className="bg-white rounded-xl shadow-md overflow-hidden hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1">
                                <div className="relative h-48 bg-gray-100">
                                    {product.photos && product.photos[0] ? (
                                        <img 
                                            src={`http://localhost:3001${product.photos[0]}`} 
                                            alt={product.title}
                                            className="w-full h-full object-cover"
                                        />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center text-5xl">
                                            {getCategoryIcon(product.category)}
                                        </div>
                                    )}
                                    <span className={`absolute top-2 right-2 px-2 py-1 rounded-full text-xs font-semibold ${
                                        product.condition === 'novo' ? 'bg-green-100 text-green-600' : 'bg-yellow-100 text-yellow-600'
                                    }`}>
                                        {product.condition === 'novo' ? 'Novo' : 'Semi-novo'}
                                    </span>
                                </div>
                                <div className="p-4">
                                    <h3 className="font-semibold text-gray-800 mb-1 line-clamp-2">{product.title}</h3>
                                    <p className="text-xl font-bold text-primary-600 mb-2">
                                        {product.price.toLocaleString()} Kz
                                    </p>
                                    <div className="flex items-center justify-between text-sm text-gray-500">
                                        <div className="flex items-center">
                                            <FiMapPin className="mr-1" size={14} />
                                            <span>{product.location}</span>
                                        </div>
                                        <span>{product.sellerName}</span>
                                    </div>
                                </div>
                            </div>
                        </Link>
                    ))}
                </div>
            )}
        </div>
    );
};

export default Home;
